"""Project-wide paths and constants.

Every script and chapter resolves file locations through this module, so the
same code runs on the licensed real data, on the synthetic data, inside
Docker or on a laptop, without editing a single path.

The data root is chosen by the environment variable ``JSEMICRO_DATA``:

* unset or ``real``  -> ``<repo>/data/real``      (licensed Refinitiv exports; never committed)
* ``synthetic``      -> ``<repo>/data/synthetic`` (generated by ``jsemicro.synthetic``)
* any other value    -> that directory

Each data root has the same layout::

    raw/    the two raw exports exactly as delivered (*.csv.gz)
    clean/  flattened, trimmed and merged intermediate files
    out/    cached analysis results read by the book
"""
from __future__ import annotations

import os
from pathlib import Path

REPO = Path(__file__).resolve().parents[2]

RICS = ["AGLJ.J", "GRTJ.J"]
TZ_LOCAL = "Africa/Johannesburg"


def data_root() -> Path:
    """Directory holding ``raw/``, ``clean/`` and ``out/`` for the active data mode."""
    mode = os.environ.get("JSEMICRO_DATA", "real")
    if mode in ("real", "synthetic"):
        return REPO / "data" / mode
    return Path(mode).expanduser().resolve()


def data_mode() -> str:
    """``"real"`` or ``"synthetic"`` (anything else counts as real data)."""
    return "synthetic" if os.environ.get("JSEMICRO_DATA") == "synthetic" else "real"


def _find_raw(pattern: str) -> Path:
    hits = sorted((data_root() / "raw").glob(pattern))
    return hits[0] if hits else data_root() / "raw" / pattern.replace("*", "")


class Paths:
    """All file locations for the active data root (evaluated lazily)."""

    @property
    def raw_dir(self) -> Path: return data_root() / "raw"
    @property
    def clean_dir(self) -> Path: return data_root() / "clean"
    @property
    def out_dir(self) -> Path: return data_root() / "out"

    # raw exports (names as delivered by Refinitiv TRTH; matched by pattern)
    @property
    def raw_tx(self) -> Path: return _find_raw("*Transactions*.gz")
    @property
    def raw_md(self) -> Path: return _find_raw("*MarketDepth*.gz")

    # Part I -- data engineering
    @property
    def tx_flat(self) -> Path: return self.clean_dir / "AGL_GRT_TX_flat.csv"
    @property
    def tx_trimmed(self) -> Path: return self.clean_dir / "AGL_GRT_TX_trimmed.csv"
    @property
    def md_flat(self) -> Path: return self.clean_dir / "AGL_GRT_MD_flat.parquet"
    @property
    def merged(self) -> Path: return self.clean_dir / "AGL_GRT_merged.parquet"
    @property
    def sort_chunks(self) -> Path: return self.clean_dir / "sort_chunks"
    @property
    def merged_sorted(self) -> Path: return self.clean_dir / "AGL_GRT_merged_sorted.parquet"
    @property
    def stage4(self) -> Path: return self.clean_dir / "AGL_GRT_stage4_final.parquet"
    @property
    def auction_prices(self) -> Path: return self.out_dir / "daily_auction_prices.csv"

    # Part III -- Hawkes outputs
    @property
    def hawkes_dir(self) -> Path: return self.out_dir / "hawkes"


PATHS = Paths()
